static RULE_TERM: [u16; 19] = [
    65535, 65535, term::LET, term::PRINT, term::IF, term::THEN, term::ELSE, term::PLUS, term::MINUS,
    term::TIMES, term::LPAR, term::RPAR, term::COMMA, term::SEMI, term::EQ, term::AT, term::NUM,
    term::IDENT, term::STR,
];
const LEX_START: usize = 1;
const LEX_ACCEPT_FROM: usize = 17;

/// What the lexer could not do at the error position.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum LexErrorReason {
    /// No rule matches.
    NoMatch,
    /// A rule matches, but its value does not fit the Rust type (a numeral beyond `u64`).
    Unrepresentable,
    /// End of input inside a nested mode.
    EndInMode,
    /// The input is longer than `u32::MAX` bytes.
    TooLong,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct LexError {
    /// Character offset, as in Lean's `LexError.pos`.
    pub pos: usize,
    /// Byte offset.
    pub byte_pos: usize,
    /// The offending character; none at end of input.
    pub ch: Option<char>,
    pub reason: LexErrorReason,
}

fn lex_error(src: &str, byte_pos: usize, reason: LexErrorReason) -> LexError {
    LexError {
        pos: src[..byte_pos].chars().count(),
        byte_pos,
        ch: src[byte_pos..].chars().next(),
        reason,
    }
}

/// `lpg_kernel::lex` with this lexer's tables: the tokens of `src`, with the terminal
/// `TERM_HOOK` for the rules whose terminal depends on the text.
pub fn lex(src: &[u8], out: &mut Vec<Token>) -> Result<(), lpg_kernel::LexFail> {
    lpg_kernel::lex(src, out, &LEX_CLASS, &LEX_TRANS, &LEX_ACCEPT, LEX_START, LEX_ACCEPT_FROM,
        &RULE_TERM, EOF)
}

/// Longest-match tokenization of `src`, appending to `out` (which is not cleared).
/// The last token pushed is the end-of-input token. A token has no value; `token_value`
/// rebuilds it from the source text of its span. The loop is `lpg_kernel::lex`; the
/// terminals that depend on the text, and the values that may not fit their Rust
/// type, are computed after it, and the first error in the source is reported.
pub fn tokenize(src: &str, out: &mut Vec<Token>) -> Result<(), LexError> {
    let first = out.len();
    let res = lex(src.as_bytes(), out);
    for i in first..out.len() {
        let t = &mut out[i];
        let text = &src[t.start as usize..t.end as usize];
        let ok = match t.rule {
            16 => lexrt::to_int(text).is_some(),
            _ => true,
        };
        if !ok {
            let at = t.start as usize;
            out.truncate(i);
            return Err(lex_error(src, at, LexErrorReason::Unrepresentable));
        }
    }
    match res {
        Ok(()) => Ok(()),
        Err(lpg_kernel::LexFail::NoMatch(pos)) => Err(lex_error(src, pos, LexErrorReason::NoMatch)),
        Err(lpg_kernel::LexFail::TooLong) => {
            Err(LexError { pos: 0, byte_pos: 0, ch: None, reason: LexErrorReason::TooLong })
        }
    }
}

pub const NUM_TERMINALS: usize = 19;
pub const NUM_NONTERMINALS: usize = 9;
pub const NUM_PRODUCTIONS: usize = 27;
pub const NUM_STATES: usize = 50;
const NONE: usize = 65535;
/// The augmented start production.
pub const AUG_PROD: usize = 26;

static TERM_NAMES: [&str; 19] = [
    "LET", "PRINT", "IF", "THEN", "ELSE", "PLUS", "MINUS", "TIMES", "LPAR", "RPAR", "COMMA", "SEMI",
    "EQ", "AT", "IDENT", "STR", "NUM", "EOF", "$",
];

static NONTERM_NAMES: [&str; 9] = [
    "program", "stmts", "stmt", "expr", "sum", "prod", "atom", "separated_list_COMMA_expr", "S'",
];

pub fn term_name(t: u16) -> &'static str {
    TERM_NAMES[t as usize]
}

pub fn nonterm_name(n: usize) -> &'static str {
    NONTERM_NAMES[n]
}

/// The left-hand side nonterminal of production `p`.
pub fn prod_lhs(p: usize) -> usize {
    LHS[p] as usize
}

/// The number of right-hand side symbols of production `p`.
pub fn prod_len(p: usize) -> usize {
    RHS_LEN[p] as usize
}

